package pe.upn.yapaa_api.service;
import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.jdbc.core.JdbcTemplate;import pe.upn.yapaa_api.repository.NegocioRepository;import pe.upn.yapaa_api.security.UsuarioActual;import pe.upn.yapaa_api.exception.*;import java.util.*;import java.math.*;import java.time.*;
@Service public class DeliveryService {
 public record Ubicacion(String direccion,double latitud,double longitud){}
 public record Cotizacion(String id,int idDireccion,int idNegocio,BigDecimal kilometros,BigDecimal importe,LocalDateTime vence,String direccion){}
 private final JdbcTemplate jdbc;private final DireccionesService direcciones;private final RutasService rutas;private final NegocioRepository negocios;private final UsuarioActual usuario;private final MapasService mapas;private final Clock reloj;private final pe.upn.yapaa_api.security.LimiteIntentos limite;
 public DeliveryService(JdbcTemplate j,DireccionesService d,RutasService r,NegocioRepository n,UsuarioActual u,MapasService m,Clock c,pe.upn.yapaa_api.security.LimiteIntentos l){jdbc=j;direcciones=d;rutas=r;negocios=n;usuario=u;mapas=m;reloj=c;limite=l;}
 public static BigDecimal tarifa(double metros){if(!Double.isFinite(metros)||metros<0||metros>6000)throw new ReglaNegocioException("El delivery está disponible hasta 6 km por calles. Elige otra dirección o recojo.");return BigDecimal.valueOf(4+Math.max(0,metros/1000-2)).multiply(BigDecimal.valueOf(2)).setScale(0,RoundingMode.CEILING).divide(BigDecimal.valueOf(2)).setScale(2);}
 private pe.upn.yapaa_api.model.Negocio negocio(int id){return negocios.findById(id).orElseThrow(()->new RecursoNoEncontradoException("Negocio no encontrado."));}
 @Transactional(readOnly=true) public Ubicacion origen(int id){usuario.verificarNegocio(negocio(id));return leerOrigen(id);}
 private Ubicacion leerOrigen(int id){return jdbc.query("SELECT direccion,latitud,longitud FROM ubicacion_negocio WHERE id_negocio=?",(r,n)->new Ubicacion(r.getString(1),r.getDouble(2),r.getDouble(3)),id).stream().findFirst().orElse(null);}
 @Transactional public Ubicacion guardarOrigen(int id,String token){usuario.verificarNegocio(negocio(id));var p=mapas.validar(token);CoberturaTrujillo.exigir(p.latitud(),p.longitud());jdbc.queryForObject("SELECT id_negocio FROM negocio WITH(UPDLOCK,HOLDLOCK) WHERE id_negocio=?",Integer.class,id);if(jdbc.update("UPDATE ubicacion_negocio SET direccion=?,latitud=?,longitud=?,fecha=SYSDATETIME() WHERE id_negocio=?",p.direccion(),p.latitud(),p.longitud(),id)==0)jdbc.update("INSERT INTO ubicacion_negocio(id_negocio,direccion,latitud,longitud) VALUES(?,?,?,?)",id,p.direccion(),p.latitud(),p.longitud());return leerOrigen(id);}
 public Cotizacion cotizar(int idNegocio,int idDireccion){int cuenta=direcciones.cliente();limite.comprobar("rutas:"+cuenta,150);var n=negocio(idNegocio);if(!Boolean.TRUE.equals(n.getActivo())||!"APROBADO".equals(n.getEstadoAprobacion()))throw new ReglaNegocioException("El negocio no está disponible.");var d=direcciones.propia(idDireccion);var o=leerOrigen(idNegocio);if(o==null)throw new ReglaNegocioException("Este negocio aún no habilita delivery. Puedes elegir recojo.");double metros=rutas.distancia(o.latitud(),o.longitud(),d.latitud(),d.longitud());BigDecimal importe=tarifa(metros),km=BigDecimal.valueOf(metros/1000).setScale(3,RoundingMode.HALF_UP);String id=UUID.randomUUID().toString();LocalDateTime vence=LocalDateTime.now(reloj).plusMinutes(10);String direccion=d.direccion()+(d.referencia().isBlank()?"":" · "+d.referencia());jdbc.update("INSERT INTO cotizacion_delivery(id,id_cuenta,id_negocio,id_direccion,direccion,latitud,longitud,origen_latitud,origen_longitud,kilometros,importe,vence) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",id,cuenta,idNegocio,idDireccion,direccion,d.latitud(),d.longitud(),o.latitud(),o.longitud(),km,importe,vence);return new Cotizacion(id,idDireccion,idNegocio,km,importe,vence,direccion);}
 // Se consume dentro de la misma transaccion del pedido; un fallo de stock revierte el consumo.
 @Transactional public Cotizacion consumir(int idNegocio,String id){int cuenta=direcciones.cliente();if(id==null||!id.matches("[a-fA-F0-9-]{36}"))throw new ReglaNegocioException("Selecciona una dirección y calcula el delivery.");var datos=jdbc.queryForList("SELECT * FROM cotizacion_delivery WITH(UPDLOCK,HOLDLOCK) WHERE id=? AND id_cuenta=? AND id_negocio=?",id,cuenta,idNegocio);if(datos.isEmpty())throw new ReglaNegocioException("La cotización no pertenece a este pedido.");var d=datos.getFirst();if(Boolean.TRUE.equals(d.get("utilizada"))||!((java.sql.Timestamp)d.get("vence")).toLocalDateTime().isAfter(LocalDateTime.now(reloj)))throw new ReglaNegocioException("La cotización venció. Vuelve a calcular el delivery.");int idDireccion=((Number)d.get("id_direccion")).intValue();direcciones.propia(idDireccion);var o=leerOrigen(idNegocio);if(o==null||Double.compare(o.latitud(),((Number)d.get("origen_latitud")).doubleValue())!=0||Double.compare(o.longitud(),((Number)d.get("origen_longitud")).doubleValue())!=0)throw new ReglaNegocioException("Cambió el punto de recojo. Vuelve a calcular el delivery.");jdbc.update("UPDATE cotizacion_delivery SET utilizada=1 WHERE id=?",id);return new Cotizacion(id,idDireccion,idNegocio,(BigDecimal)d.get("kilometros"),(BigDecimal)d.get("importe"),((java.sql.Timestamp)d.get("vence")).toLocalDateTime(),(String)d.get("direccion"));}
}
